    private void toggle(LinearLayout content,String title,String detail,String key,boolean defaultValue){
        android.widget.Switch control=new android.widget.Switch(host);control.setText(title+(detail.isEmpty()?"":"\n"+detail));control.setTextSize(17);control.setTextColor(text);control.setMinHeight(dp(76));control.setPadding(dp(12),dp(10),dp(12),dp(10));control.setChecked(preferences().getBoolean(key,defaultValue));content.addView(control,new LinearLayout.LayoutParams(-1,-2));
        control.setOnCheckedChangeListener((v,checked)->{preferences().edit().putBoolean(key,checked).apply();host.mapPreferencesChanged();});
    }
    private void choose(String title,String key,String[] choices,int selected,Runnable after){new AlertDialog.Builder(host).setTitle(title).setSingleChoiceItems(choices,Math.max(0,Math.min(choices.length-1,selected)),(d,n)->{if("voice_language".equals(key)&&voiceLanguageChangeBlocked(Store.route!=null,selected,n)){d.dismiss();host.error(host.getString(R.string.voice_language_requires_replan));return;}preferences().edit().putInt(key,n).apply();d.dismiss();host.mapPreferencesChanged();after.run();}).setNegativeButton(host.getString(R.string.action_cancel),null).show();}
    static boolean voiceLanguageChangeBlocked(boolean routeExists,int selected,int requested){return routeExists&&selected!=requested;}
    private void selection(LinearLayout content,String title,String key,String[] options,int fallback,Runnable after){int n=preferences().getInt(key,fallback);addRow(content,title,options[Math.max(0,Math.min(options.length-1,n))],()->choose(title,key,options,n,after));}
