        String driving=host.getString(R.string.route_driving_mode_title),drivingValue=host.getString(preferences().getBoolean("map_3d",true)?R.string.route_driving_row_3d_course:preferences().getBoolean("north_up",false)?R.string.route_driving_row_2d_north:R.string.route_driving_row_2d_course);
