    private void deletePhoto(String id){if(id.matches("[a-fA-F0-9-]{36}"))new File(host.getFilesDir(),"profile-photos/"+id+".jpg").delete();}
    private String number(double n){return java.math.BigDecimal.valueOf(n).stripTrailingZeros().toPlainString();}
    private void commit(JSONObject p,boolean engine){data().replace(p);if(engine&&data().active.equals(p.optString("id")))host.profileChanged(VehicleProfiles.truck(p));}
    private void number(String id,String key,String title,String unit){JSONObject p=data().find(id);EditText input=new EditText(host);input.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);input.setSingleLine();input.setText(number(p.optDouble(key)));input.selectAll();input.setContentDescription(host.getString(R.string.profile_number_accessibility,title,unit));AlertDialog dialog=new AlertDialog.Builder(host).setTitle(title+(unit.isEmpty()?"":" ("+unit+")")).setView(input).setNegativeButton(host.getString(R.string.action_cancel),null).setPositiveButton(host.getString(R.string.action_save),null).create();dialog.show();dialog.getButton(-1).setOnClickListener(v->{try{double n=Double.parseDouble(input.getText().toString().replace(',','.'));if(!Double.isFinite(n))throw new IllegalArgumentException(host.getString(R.string.profile_error_finite));if(Arrays.asList("axles","trailers","year").contains(key)&&n!=Math.rint(n))throw new IllegalArgumentException(host.getString(R.string.profile_error_whole));if(key.equals("trailers")&&(n<0||n>10))throw new IllegalArgumentException(host.getString(R.string.profile_error_trailers));if(key.equals("year")&&(n<1900||n>Calendar.getInstance().get(Calendar.YEAR)+1))throw new IllegalArgumentException(host.getString(R.string.profile_error_year));JSONObject edited=VehicleProfiles.copy(p);edited.put(key,n);VehicleProfiles.truck(edited);commit(edited,!Arrays.asList("trailers","year").contains(key));dialog.dismiss();profile(id);}catch(Exception e){input.setError(e instanceof NumberFormatException?host.getString(R.string.profile_error_number):e.getMessage());}});input.requestFocus();dialog.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_VISIBLE|WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);}
    private void editText(String id){JSONObject p=data().find(id);EditText input=new EditText(host);input.setSingleLine();input.setText(p.optString("name"));AlertDialog d=new AlertDialog.Builder(host).setTitle(host.getString(R.string.profile_name_title)).setView(input).setNegativeButton(host.getString(R.string.action_cancel),null).setPositiveButton(host.getString(R.string.action_save),null).create();d.show();d.getButton(-1).setOnClickListener(v->{String name=input.getText().toString().trim();if(name.isEmpty()||name.length()>60){input.setError(host.getString(R.string.profile_name_error));return;}try{JSONObject edit=VehicleProfiles.copy(p);edit.put("name",name);commit(edit,false);d.dismiss();profile(id);}catch(Exception e){input.setError(e.getMessage());}});}
