    private static final int[] FUEL_TEXT={R.string.profile_fuel_diesel,R.string.profile_fuel_gas,R.string.profile_fuel_ethanol,R.string.profile_fuel_lpg,R.string.profile_fuel_cng,R.string.profile_fuel_lng,R.string.profile_fuel_hydrogen,R.string.profile_fuel_electric};
    private static final String[] EMISSIONS={"Unspecified","Euro 1","Euro 2","Euro 3","Euro 4","Euro 5","Euro 6"};
